COMMENT ON COLUMN "football"."match_h2h_summaries"."feature_code" IS 'Fixed family.';

COMMENT ON COLUMN "football"."match_h2h_summaries"."variant_key" IS 'Exact immutable parent variant.';

COMMENT ON COLUMN "football"."match_h2h_summaries"."recorded_from_gen" IS 'Parent version key, not an independent history interval.';

