COMMENT ON COLUMN "football"."match_h2h_summaries"."draws" IS 'Exact native supplied total; never inferred from entries.';

COMMENT ON COLUMN "football"."match_h2h_summaries"."draws_state" IS 'Exact native property state.';

COMMENT ON COLUMN "football"."match_h2h_summaries"."total_matches" IS 'Exact native supplied total; never inferred from entries.';

COMMENT ON COLUMN "football"."match_h2h_summaries"."total_matches_state" IS 'Exact native property state.';

