        IF NEW."recorded_to_gen" IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='A new typed version must have an open interval';
        END IF;
    ELSE
        IF ROW(NEW."id",NEW."player_id",NEW."external_profile_version_id",NEW."display_name",NEW."image_asset_id",NEW."observed_at",NEW."source_id",NEW."source_record_id",NEW."canonical_policy_version",NEW."data_revision",NEW."quality_flags",NEW."updated_at",NEW."short_name",NEW."country_code_source",NEW."raw_position_code",NEW."shirt_number",NEW."birth_date",NEW."height_cm",NEW."dominant_foot",NEW."profile_content_sha256",NEW."nationality_country_id",NEW."primary_position_code",NEW."recorded_from_gen",NEW."variant_key",NEW."is_canonical",NEW."is_deleted",NEW."profile_context",NEW."relation_code",NEW."contract_version",NEW."transform_version",NEW."transform_code_sha256",NEW."provenance_kind",NEW."nationality_country_revision_id",NEW."primary_position_definition_version",NEW."raw_position_code_state",NEW."raw_position_code_source_number",NEW."shirt_number_state",NEW."shirt_number_source_number",NEW."source_name_state",NEW."source_image_url",NEW."source_image_url_state",NEW."source_external_id_state") IS DISTINCT FROM ROW(OLD."id",OLD."player_id",OLD."external_profile_version_id",OLD."display_name",OLD."image_asset_id",OLD."observed_at",OLD."source_id",OLD."source_record_id",OLD."canonical_policy_version",OLD."data_revision",OLD."quality_flags",OLD."updated_at",OLD."short_name",OLD."country_code_source",OLD."raw_position_code",OLD."shirt_number",OLD."birth_date",OLD."height_cm",OLD."dominant_foot",OLD."profile_content_sha256",OLD."nationality_country_id",OLD."primary_position_code",OLD."recorded_from_gen",OLD."variant_key",OLD."is_canonical",OLD."is_deleted",OLD."profile_context",OLD."relation_code",OLD."contract_version",OLD."transform_version",OLD."transform_code_sha256",OLD."provenance_kind",OLD."nationality_country_revision_id",OLD."primary_position_definition_version",OLD."raw_position_code_state",OLD."raw_position_code_source_number",OLD."shirt_number_state",OLD."shirt_number_source_number",OLD."source_name_state",OLD."source_image_url",OLD."source_image_url_state",OLD."source_external_id_state")
           OR OLD."recorded_to_gen" IS NOT NULL OR NEW."recorded_to_gen" IS NULL
           OR NEW."recorded_to_gen" <= OLD."recorded_from_gen" THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Typed values are immutable; an open interval closes once';
        END IF;
        PERFORM ingest.assert_draft_generation(NEW."recorded_to_gen");
    END IF;
    RETURN NEW;
END;
$orion_pro$;
