IF EXISTS (SELECT 1 FROM "ingest"."match_coverage" fresh JOIN "ingest"."match_coverage" old ON fresh."match_id" IS NOT DISTINCT FROM old."match_id" AND fresh."source_id" IS NOT DISTINCT FROM old."source_id" AND fresh."feature_code" IS NOT DISTINCT FROM old."feature_code" AND fresh."variant_key" IS NOT DISTINCT FROM old."variant_key" WHERE fresh."recorded_from_gen"=g AND old."recorded_to_gen"=g AND ROW(old."match_id",old."source_id",old."feature_code",old."coverage_state",old."http_status",old."error_code",old."observed_row_count",old."document_id",old."is_stale",old."variant_key",old."is_canonical",old."collection_state",old."relation_code",old."contract_version",old."transform_version",old."transform_code_sha256",old."source_record_id",old."provenance_kind",old."match_revision_id",old."source_match_id_state",old."source_home_team_profile_version_id",old."source_home_team_state",old."source_away_team_profile_version_id",old."source_away_team_state") IS NOT DISTINCT FROM ROW(fresh."match_id",fresh."source_id",fresh."feature_code",fresh."coverage_state",fresh."http_status",fresh."error_code",fresh."observed_row_count",fresh."document_id",fresh."is_stale",fresh."variant_key",fresh."is_canonical",fresh."collection_state",fresh."relation_code",fresh."contract_version",fresh."transform_version",fresh."transform_code_sha256",fresh."source_record_id",fresh."provenance_kind",fresh."match_revision_id",fresh."source_match_id_state",fresh."source_home_team_profile_version_id",fresh."source_home_team_state",fresh."source_away_team_profile_version_id",fresh."source_away_team_state") AND NOT EXISTS ((SELECT "event_seq","event_type","period_code","minute","minute_added","second","team_id","player_id","related_player_id","is_penalty","is_own_goal","source_event_id","source_ordinal","source_record_id","canonical_policy_version","quality_flags","score_home","score_away","match_revision_id","match_team_revision_id","period_definition_version","source_event_type_state","source_minute_st